#include "hip_api.h"
#include <algorithm>
#include <cstring>
#include <chrono>
#include <cmath>
using namespace hip_probe;
static std::vector<unsigned char>Read(const char*p){std::ifstream f(p,std::ios::binary|std::ios::ate);if(!f)throw std::runtime_error("open input");std::vector<unsigned char>v(size_t(f.tellg()));f.seekg(0);if(!f.read((char*)v.data(),v.size()))throw std::runtime_error("read input");return v;}
int main(int argc,char**argv)try{
 setvbuf(stdout,nullptr,_IONBF,0);if(argc!=7)throw std::runtime_error("STOCK CAND INPUT FW GOLD OUTDIR");auto indata=Read(argv[3]),fw=Read(argv[4]),gold=Read(argv[5]);if(indata.size()!=655360||fw.size()!=3145856||gold.size()!=1966080)throw std::runtime_error("typed span");
 Api a(7);a.Check(a.hipInit(0),"init");a.Check(a.hipSetDevice(0),"device");auto props=a.Properties(0);if(std::string(props.gcnArchName).rfind("gfx1201",0)||!std::strstr(props.name,"9070 XT"))throw std::runtime_error("actual9070XT scope");Handle oldm{},newm{},oldf{},newf{},stream{};a.Check(a.LoadModule(&oldm,argv[1]),"stock");a.Check(a.LoadModule(&newm,argv[2]),"candidate");a.Check(a.hipModuleGetFunction(&oldf,oldm,"vit_stream_qkv_frag_bin_w5f8"),"old fn");a.Check(a.hipModuleGetFunction(&newf,newm,"vit_stream_qkv_frag_bin_w5f8_vtail"),"new fn");a.Check(a.hipStreamCreate(&stream),"stream");
 void*in{},*weight{},*out{},*gate=nullptr;unsigned tokens=640;a.Check(a.hipMalloc(&in,indata.size()),"input");a.Check(a.hipMalloc(&weight,fw.size()),"weight");a.Check(a.hipMalloc(&out,gold.size()+256),"output");a.Check(a.hipMemcpy(in,indata.data(),indata.size(),1),"input upload");a.Check(a.hipMemcpy(weight,fw.data(),fw.size(),1),"weight upload");std::vector<unsigned char>first;
 Handle begin{},end{};a.Check(a.hipEventCreate(&begin),"eventbegin");a.Check(a.hipEventCreate(&end),"eventend");
 struct Sample{unsigned slot,role,iteration;float gpu;double wall;};std::vector<Sample>samples;samples.reserve(120);
 auto check=[&](unsigned slot,unsigned edge){std::vector<unsigned char>v(gold.size()),tail(256);a.Check(a.hipMemcpy(v.data(),out,v.size(),2),"edge read");a.Check(a.hipMemcpy(tail.data(),(char*)out+v.size(),256,2),"guardread");size_t diff=0,nan=0,guard=0;for(size_t i=0;i<v.size();i++){diff+=v[i]!=gold[i];nan+=(v[i]&127)==127;}for(auto x:tail)guard+=x!=90;printf("EDGE slot=%u edge=%u byte_diff=%zu nan=%zu guard_diff=%zu\n",slot,edge,diff,nan,guard);if(diff||nan||guard)throw std::runtime_error("edgegold");};
 for(unsigned slot=0;slot<4;slot++){unsigned role=(slot==1||slot==2);a.Check(a.hipMemsetAsync(out,127,gold.size(),stream),"slotpoison");a.Check(a.hipMemsetAsync((char*)out+gold.size(),90,256,stream),"slottail");a.Check(a.hipStreamSynchronize(stream),"slotsetupoutside");
  for(unsigned i=0;i<30;i++){void*args[]={&in,&weight,&out,&tokens,&gate};auto start=std::chrono::steady_clock::now();a.Check(a.hipEventRecord(begin,stream),"begin");a.Check(a.hipModuleLaunchKernel(role?newf:oldf,768,1,1,160,1,1,0,stream,args,nullptr),"QKV");a.Check(a.hipEventRecord(end,stream),"end");a.Check(a.hipEventSynchronize(end),"complete");double wall=std::chrono::duration<double,std::milli>(std::chrono::steady_clock::now()-start).count();float gpu{};a.Check(a.hipEventElapsedTime(&gpu,begin,end),"elapsed");if(!std::isfinite(gpu)||gpu<=0||!std::isfinite(wall)||wall<=0)throw std::runtime_error("invalidtime no retry");samples.push_back({slot,role,i,gpu,wall});if(i==9||i==29)check(slot,i);}
 }
 std::ofstream csv(std::string(argv[6])+"/samples.csv");csv<<"slot,role,iteration,warm,gpu_ms,wall_ms\n";csv.precision(9);for(auto&q:samples)csv<<q.slot<<","<<q.role<<","<<q.iteration<<","<<(q.iteration<10)<<","<<q.gpu<<","<<q.wall<<"\n";csv.close();a.Check(a.hipEventDestroy(begin),"destroybegin");a.Check(a.hipEventDestroy(end),"destroyend");puts("BOUNDED_QKV_PAIR_SCREEN_A_B_B_A_10WARM20MEASURE_NOT_FRAME_PERFORMANCE");
 a.Check(a.hipFree(in),"freein");a.Check(a.hipFree(weight),"freeweight");a.Check(a.hipFree(out),"freeout");a.Check(a.hipStreamDestroy(stream),"streamdestroy");a.Check(a.hipModuleUnload(newm),"newunload");a.Check(a.hipModuleUnload(oldm),"oldunload");return 0;
}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}
